import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.C-zpCNjM.js";var i=JSON.parse(`{"title":"Select Field","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/field-types/select.md","filePath":"documentation/field-types/select.md","lastUpdated":1788551488000}`),a={name:`documentation/field-types/select.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="select-field" tabindex="-1">Select Field <a class="header-anchor" href="#select-field" aria-label="Permalink to “Select Field”">​</a></h1><p>The <strong>Select</strong> field type automates single-choice dropdown menus (<code>&lt;select&gt;</code>) by matching options against Excel (<code>.xlsx</code>) row values or static default text.</p><hr><h2 id="basic-configuration" tabindex="-1">Basic Configuration <a class="header-anchor" href="#basic-configuration" aria-label="Permalink to “Basic Configuration”">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><strong>Field Name</strong></td><td>Unique identifier for the field in the workflow</td><td><code>country</code>, <code>department</code></td></tr><tr><td><strong>Field Type</strong></td><td>Set to <strong>Select</strong></td><td><code>Select</code></td></tr><tr><td><strong>Field Selector Type</strong></td><td>Element locator method</td><td><code>Selector</code>, <code>XPath</code>, <code>Id</code></td></tr><tr><td><strong>Field Selector Query</strong></td><td>CSS selector or XPath targeting the <code>&lt;select&gt;</code> element</td><td><code>select[name=&quot;country&quot;]</code>, <code>#category</code></td></tr><tr><td><strong>Field Value</strong></td><td>Option text, value, or column to match</td><td>Excel (<code>.xlsx</code>) column name or static value</td></tr></tbody></table><hr><h2 id="match-options-as" tabindex="-1">Matching Strategies <a class="header-anchor" href="#match-options-as" aria-label="Permalink to “Matching Strategies”">​</a></h2><p>Under <strong>Match options as</strong>, choose how the extension identifies which <code>&lt;option&gt;</code> to select:</p><table tabindex="0"><thead><tr><th>Strategy</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><strong>Through Name/Value (Default)</strong></td><td>Matches either visible label text or underlying <code>value=&quot;&quot;</code> attribute.</td><td><code>US</code> or <code>United States</code></td></tr><tr><td><strong>Equal to Name</strong></td><td>Matches only against the visible option text (exact label).</td><td><code>United States</code></td></tr><tr><td><strong>Equal to Value</strong></td><td>Matches only against the HTML <code>value</code> attribute.</td><td><code>value=&quot;US&quot;</code></td></tr><tr><td><strong>Search Name in Any Position</strong></td><td>Matches if the search term appears anywhere inside option text.</td><td><code>States</code> matches <code>United States</code></td></tr><tr><td><strong>Match Name from Start-End</strong></td><td>Matches if option text starts or ends with the provided value.</td><td><code>United</code> or <code>States</code></td></tr><tr><td><strong>Through Option Serial Number</strong></td><td>Selects an option by its 1-based numerical index.</td><td><code>1</code> selects the 1st option</td></tr></tbody></table><hr><h2 id="select-field-settings" tabindex="-1">Field Settings <a class="header-anchor" href="#select-field-settings" aria-label="Permalink to “Field Settings”">​</a></h2><p>Configure dropdown-specific behaviors to handle dynamic lists and text variations:</p><h3 id="dynamic-loading-timing" tabindex="-1">Dynamic Loading &amp; Timing <a class="header-anchor" href="#dynamic-loading-timing" aria-label="Permalink to “Dynamic Loading &amp; Timing”">​</a></h3><ul><li><strong>Wait until max options in the dropdown element</strong>: Waits until the dropdown contains at least the specified number of options (default: <code>2</code>). Useful for AJAX-loaded or cascading dropdowns.</li><li><strong>Wait until the dropdown option is selected</strong>: Pauses until the selected option is confirmed active before advancing to subsequent fields.</li></ul><h3 id="text-normalization" tabindex="-1">Text Normalization <a class="header-anchor" href="#text-normalization" aria-label="Permalink to “Text Normalization”">​</a></h3><ul><li><strong>Convert the text into lowercase letters and then match the text</strong>: Enables case-insensitive matching (<code>united states</code> matches <code>United States</code>).</li><li><strong>Remove extra space from option text then match the text</strong>: Trims leading/trailing whitespace and normalizes multiple spaces into a single space.</li><li><strong>Remove all space from option text then match the text</strong>: Strips all whitespace for strict comparison (<code>UnitedStates</code> matches <code>United States</code>).</li></ul><hr><h2 id="managing-options" tabindex="-1">Modifying &amp; Adding Dropdown Options <a class="header-anchor" href="#managing-options" aria-label="Permalink to “Modifying &amp; Adding Dropdown Options”">​</a></h2><p>In dynamic workflows, you may need to update an existing choice or inject a new option into the <code>&lt;select&gt;</code> element before making a selection.</p><h3 id="how-to-edit-option" tabindex="-1">How to Edit an Existing Option (<code>&lt;option&gt;</code>) <a class="header-anchor" href="#how-to-edit-option" aria-label="Permalink to “How to Edit an Existing Option (&lt;option&gt;)”">​</a></h3><p>To update an existing option&#39;s attributes (such as changing its <code>value</code> attribute), use the <a href="/documentation/functions.html#insertelementattribute"><code>insertElementAttribute</code></a> predefined function:</p><table tabindex="0"><thead><tr><th>Property</th><th>Value / Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Field Type</strong></td><td><strong>Function</strong></td><td>Set to predefined function runner</td></tr><tr><td><strong>Function Name</strong></td><td><code>insertElementAttribute</code></td><td>Updates or adds element attributes</td></tr><tr><td><strong>Selector Type</strong></td><td><code>XPath</code></td><td>Pinpoints the specific <code>&lt;option&gt;</code> node</td></tr><tr><td><strong>Selector Query</strong></td><td><code>//select/option[@value=&quot;100&quot;]</code></td><td>Targets <code>&lt;option&gt;</code> with <code>value=&quot;100&quot;</code> inside the <code>&lt;select&gt;</code></td></tr><tr><td><strong>Field Value</strong></td><td><code>value,1000</code></td><td>Format: <code>attributeName,attributeValue</code> (updates <code>value=&quot;100&quot;</code> to <code>value=&quot;1000&quot;</code>)</td></tr></tbody></table><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>Required Setting</strong>: Because <code>&lt;option&gt;</code> elements inside a standard <code>&lt;select&gt;</code> dropdown have no visible layout box when the dropdown is closed, you <strong>MUST turn OFF</strong> the field option: <strong><code>Wait until element is visible in the page.</code></strong> in <a href="/documentation/form-fields/field-settings.html">Field Settings</a>.</p><p>Leaving this option ON will cause a visibility timeout error.</p></div><hr><h3 id="how-to-add-option" tabindex="-1">How to Add a New Option (<code>&lt;option&gt;</code>) <a class="header-anchor" href="#how-to-add-option" aria-label="Permalink to “How to Add a New Option (&lt;option&gt;)”">​</a></h3><p>To dynamically insert a new choice into an existing dropdown, use the <a href="/documentation/field-types/others/insert-remove-html.html"><strong>Insert &amp; Remove HTML</strong></a> field type:</p><table tabindex="0"><thead><tr><th>Property</th><th>Value / Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Field Type</strong></td><td><strong>Insert &amp; Remove HTML</strong></td><td>Direct DOM element injection</td></tr><tr><td><strong>Selector Type</strong></td><td><code>Selector</code> or <code>XPath</code></td><td>Targets the parent <code>&lt;select&gt;</code> element</td></tr><tr><td><strong>Selector Query</strong></td><td><code>select#country</code> or <code>//select[@name=&quot;category&quot;]</code></td><td>The target dropdown container</td></tr><tr><td><strong>Position of New HTML Content</strong></td><td><code>beforeend</code></td><td>Inserts the new option at the end of the dropdown list</td></tr><tr><td><strong>Field Default Value</strong></td><td><code>&lt;option value=&quot;1000&quot;&gt;1000&lt;/option&gt;</code></td><td>Raw HTML markup for the new option</td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p></p><ul><li>Use <strong><code>beforeend</code></strong> to append the option at the bottom of the list.</li><li>Use <strong><code>afterbegin</code></strong> to insert the option as the very first item in the dropdown.</li></ul></div><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><table tabindex="0"><thead><tr><th>Issue</th><th>Likely Cause</th><th>Solution</th></tr></thead><tbody><tr><td><strong>Option not found</strong></td><td>Capitalization mismatch or extra spacing</td><td>Turn ON lowercase matching or space normalization.</td></tr><tr><td><strong>Dropdown empty when field runs</strong></td><td>Options load asynchronously via AJAX</td><td>Turn ON <strong>Wait until max options in the dropdown element</strong> and set count to <code>2</code> or higher.</td></tr><tr><td><strong>Selection doesn&#39;t trigger page updates</strong></td><td>Custom UI library (e.g. React/Vue/Material select)</td><td>Use <a href="/documentation/field-types/material-single-select.html">Material Single Select</a> or trigger events using <a href="/documentation/field-types/javascript-events.html">JavaScript Events</a>.</td></tr></tbody></table><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next Steps”">​</a></h2><ul><li><img src="/svg/form.svg" class="doc-icon"> <a href="/documentation/field-types/multiple-select.html">Multiple Select Field</a> — Automate multi-choice dropdowns</li><li><img src="/svg/settings.svg" class="doc-icon"> <a href="/documentation/form-fields/field-settings.html">Field Settings</a> — Advanced field execution options</li><li><img src="/svg/excel.svg" class="doc-icon"> <a href="/documentation/site/site-excel-template.html">Excel Template</a> — Prepare Excel (.xlsx) templates</li><li><img src="/svg/browser.svg" class="doc-icon"> <a href="/documentation/site/site-settings.html">Site Settings</a> — Configure site-wide automation settings</li></ul>`,34)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};